class Solution:
 def largestLocal(self, grid):
  n=len(grid); out=[]
  for i in range(1,n-1):
   row=[]
   for j in range(1,n-1): row.append(max(grid[x][y] for x in range(i-1,i+2) for y in range(j-1,j+2)))
   out.append(row)
  return out

class Solution:
 def minimumRecolors(self, blocks, k):
  black=blocks[:k].count("B"); best=k-black
  for i in range(k,len(blocks)):
   black += blocks[i]=="B"; black -= blocks[i-k]=="B"; best=min(best,k-black)
  return best

class Solution:
 def minNumberOfHours(self, initialEnergy, initialExperience, energy, experience):
  need=max(0,sum(energy)+1-initialEnergy); exp=initialExperience
  for e in experience:
   if exp<=e: need += e-exp+1; exp=e+1
   exp += e
  return need

class Solution:
 def removeStars(self, s):
  stack=[]
  for c in s:
   if c=="*": stack.pop()
   else: stack.append(c)
  return "".join(stack)

class Solution:
 def findSubarrays(self, nums):
  seen=set()
  for i in range(len(nums)-1):
   s=nums[i]+nums[i+1]
   if s in seen: return True
   seen.add(s)
  return False

class Solution:
 def mostFrequentEven(self, nums):
  freq={}
  for x in nums:
   if x%2==0: freq[x]=freq.get(x,0)+1
  return min(freq, key=lambda x:(-freq[x],x)) if freq else -1

class Solution:
 def smallestEvenMultiple(self, n):
  return n if n%2==0 else 2*n

class Solution:
 def sortPeople(self, names, heights):
  return [name for _,name in sorted(zip(heights,names),reverse=True)]

class Solution:
 def commonFactors(self, a, b):
  return sum(1 for x in range(1,min(a,b)+1) if a%x==0 and b%x==0)

class Solution:
 def hardestWorker(self, n, logs):
  best_id=logs[0][0]; best=logs[0][1]; prev=logs[0][1]
  for i in range(1,len(logs)):
   emp,end=logs[i]; duration=end-prev
   if duration>best or (duration==best and emp<best_id): best=duration; best_id=emp
   prev=end
  return best_id
